From 1a6ba5edc0b4482182ec6603433435ff091f66b6 Mon Sep 17 00:00:00 2001
From: Yves Rutschle <git1@rutschle.net>
Date: Sat, 27 Jan 2018 22:59:52 +0100
Subject: [PATCH] fix IPv6 parse error introduced in
 7bf3e12c30d0585743792982ed8bcfc44aecae34


diff --git a/common.c b/common.c
index 225c28a..541bac1 100644
--- a/common.c
+++ b/common.c
@@ -456,19 +456,21 @@ int resolve_split_name(struct addrinfo **out, const char* ct_host, const char* s
    struct addrinfo hint;
    char *end;
    int res;
-   char* host;
+   char* host, *host_base;

    memset(&hint, 0, sizeof(hint));
    hint.ai_family = PF_UNSPEC;
    hint.ai_socktype = SOCK_STREAM;

    /* Copy parameter so not to clobber data in libconfig */
-   res = asprintf(&host, "%s", ct_host);
+   res = asprintf(&host_base, "%s", ct_host);
    if (res == -1) {
        log_message(LOG_ERR, "asprintf: cannot allocate memory");
        return -1;
    }

+   host = host_base;
+
    /* If it is a RFC-Compliant IPv6 address ("[1234::12]:443"), remove brackets
     * around IP address */
    if (host[0] == '[') {
@@ -483,7 +485,7 @@ int resolve_split_name(struct addrinfo **out, const char* ct_host, const char* s
    res = getaddrinfo(host, serv, &hint, out);
    if (res)
       log_message(LOG_ERR, "%s `%s:%s'\n", gai_strerror(res), host, serv);
-   free(host);
+   free(host_base);
    return res;
 }

-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by incorrect memory management when allocating and freeing the host string. The original code directly used the `host` pointer for both allocation and deallocation, which could lead to memory leaks or errors if the pointer was modified before freeing. The change to use `host_base` for allocation and then assign it to `host` ensures that the correct pointer is freed, preventing potential parse errors with IPv6 addresses.

        Commit message:
        fix IPv6 parse error introduced in
 7bf3e12c30d0585743792982ed8bcfc44aecae34  

        Patch:
          */
 int resolve_split_name(struct addrinfo **out, const char* ct_host, const char* serv)
 {
    struct addrinfo hint;
    char *end;
    int res;
-   char* host;
+   char* host, *host_base;

    memset(&hint, 0, sizeof(hint));
    hint.ai_family = PF_UNSPEC;
    hint.ai_socktype = SOCK_STREAM;

    /* Copy parameter so not to clobber data in libconfig */
-   res = asprintf(&host, "%s", ct_host);
+   res = asprintf(&host_base, "%s", ct_host);
    if (res == -1) {
        log_message(LOG_ERR, "asprintf: cannot allocate memory");
        return -1;
    }

+   host = host_base;
+
    /* If it is a RFC-Compliant IPv6 address ("[1234::12]:443"), remove brackets
     * around IP address */
    if (host[0] == '[') {
        end = strrchr(host, ']');
        if (!end) {
            fprintf(stderr, "%s: no closing bracket in IPv6 address?\n", host);
        }
        host++; /* skip first bracket */
        *end = 0; /* remove last bracket */
    }

    res = getaddrinfo(host, serv, &hint, out);
    if (res)
       log_message(LOG_ERR, "%s `%s:%s'\n", gai_strerror(res), host, serv);
-   free(host);
+   free(host_base);
    return res;
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>

Code statements:
```c
-   char* host;
+   char* host, *host_base;

-   res = asprintf(&host, "%s", ct_host);
+   res = asprintf(&host_base, "%s", ct_host);

+   host = host_base;

-   free(host);
+   free(host_base);
```

